            "id": "55",
            "title": "Mass Schedule",
            "alias": "mass-times",
            "categoryId": "24",
            "categoryTitle": "Homepage Articles",
            "introtext": "\t<h1 class=\"mt-big-title\">Mass Schedule</h1>\n<h2>Sunday Mass</h2>\n<p>Saturday: 5:00 PM<br />Sunday: 7:30 AM, 9:30 AM, &amp; 11:30 AM</p>\n<h2>Daily Mass</h2>\n<p>Monday to Saturday:<br />8:30 AM</p>\n<h2>Confession</h2>\n<p>4:00 PM to 4:45 PM on Saturday &amp; by appointment at <a href=\"tel:5166281113\" target=\"_blank\" rel=\"noopener noreferrer\">516-628-1113</a> </p>\n<h2> </h2>\n<p> </p>\n<p> </p>",
